  REMINDER_HOUR: 19, // Täglich um 19:00 Uhr abends

  FIREBASE_PROJECT_ID: "moppedtagebuch",
  FIREBASE_API_KEY: "AIzaSyCU4b7reiVNHjqvuEM7cXSLGilCmZ5YYlM",
